def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator divides the grid into equal-sized panels. This avoids
    # mistaking uniform pattern rows for the separator.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            a, b = grid[:r], grid[r + 1:]
            common = set(x for row in a for x in row) & set(
                x for row in b for x in row
            )
            background = next(iter(common))
            return [[3 if a[i][j] == b[i][j] else background
                     for j in range(w)] for i in range(len(a))]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            common = set(x for row in a for x in row) & set(
                x for row in b for x in row
            )
            background = next(iter(common))
            return [[3 if a[i][j] == b[i][j] else background
                     for j in range(len(a[0]))] for i in range(h)]
